def compute(vars):
    payment_volume = vars["v1"]
    total_transactions = vars["v2"]

    if total_transactions == 0:
        return None

    value = payment_volume / total_transactions

    return {
        "value": value,
        "trace": {
            "payment_volume": payment_volume,
            "total_transactions": total_transactions,
            "calculation": "payment_volume / total_transactions",
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD per transaction"
            }
        }
    }
